interface ProjectsTableProps {
  projects: ProjectListItem[]
  selectedIds: string[]
  onToggle: (id: string) => void
  onToggleAll: (allIds: string[]) => void
}

function ProjectsTable({ projects, selectedIds, onToggle, onToggleAll }: ProjectsTableProps) {
  const allIds = projects.map((p) => p.id)
  const allSelected = allIds.length > 0 && allIds.every((id) => selectedIds.includes(id))
  const someSelected = !allSelected && allIds.some((id) => selectedIds.includes(id))

  return (
    <div className="rounded-lg border border-border overflow-hidden">
      <Table>
        <TableHeader>
          <TableRow>
            {/* Select-all checkbox */}
            <TableHead className="w-10 pl-3">
              <Checkbox
                checked={allSelected}
                data-state={someSelected ? 'indeterminate' : allSelected ? 'checked' : 'unchecked'}
                onCheckedChange={() => onToggleAll(allIds)}
                aria-label="Select all projects"
                className={someSelected ? 'opacity-70' : undefined}
              />
            </TableHead>
            <TableHead>Project</TableHead>
            <TableHead>Client</TableHead>
            <TableHead className="hidden sm:table-cell">Artist</TableHead>
            <TableHead className="hidden md:table-cell">Sessions</TableHead>
            <TableHead className="hidden lg:table-cell">Deposit</TableHead>
            <TableHead>Status</TableHead>
            <TableHead className="hidden xl:table-cell text-right">Updated</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {projects.map((project) => {
            const isSelected = selectedIds.includes(project.id)
            const clientName = project.client
              ? `${project.client.first_name}${project.client.last_name ? ` ${project.client.last_name}` : ''}`
              : '—'

            const sessionLabel = project.total_sessions_planned
              ? `${project.sessions_completed} / ${project.total_sessions_planned}`
              : `${project.sessions_completed}`

            const statusClass =
              TABLE_STATUS_CONFIG[project.status] ?? TABLE_STATUS_CONFIG.active
            const statusLabel = STATUS_LABELS[project.status] ?? project.status

            return (
              <TableRow
                key={project.id}
                className={cn(
                  'cursor-pointer hover:bg-muted/50 transition-colors',
                  isSelected && 'bg-accent/40'
                )}
                onClick={(e) => {
                  // Don't navigate if clicking the checkbox cell
                  const target = e.target as HTMLElement
                  if (target.closest('[role="checkbox"]') || target.tagName === 'BUTTON') return
                  window.location.href = `/projects/${project.id}`
                }}
              >
                {/* Per-row checkbox */}
                <TableCell className="w-10 pl-3" onClick={(e) => e.stopPropagation()}>
                  <Checkbox
                    checked={isSelected}
                    onCheckedChange={() => onToggle(project.id)}
                    aria-label={`Select ${project.name}`}
                  />
                </TableCell>
                <TableCell>
                  <div className="font-medium text-sm text-foreground line-clamp-1">
                    {project.name}
                  </div>
                  {project.placement && (
                    <div className="text-xs text-muted-foreground line-clamp-1">
                      {project.placement}
                    </div>
                  )}
                </TableCell>
                <TableCell className="text-sm text-muted-foreground">{clientName}</TableCell>
                <TableCell className="hidden sm:table-cell text-sm text-muted-foreground">
                  {project.primary_artist?.display_name ?? '—'}
                </TableCell>
                <TableCell className="hidden md:table-cell text-sm tabular-nums">
                  {sessionLabel}
                </TableCell>
                <TableCell className="hidden lg:table-cell text-sm tabular-nums">
                  {project.deposit_pool_cents > 0
                    ? formatCurrency(project.deposit_pool_cents)
                    : '—'}
                </TableCell>
                <TableCell>
                  <span
                    className={cn(
                      'px-2 py-0.5 rounded-full text-[11px] font-medium',
                      statusClass
                    )}
                  >
                    {statusLabel}
                  </span>
                </TableCell>
                <TableCell className="hidden xl:table-cell text-xs text-muted-foreground text-right">
                  {formatDate(project.updated_at)}
                </TableCell>
              </TableRow>
            )
          })}
        </TableBody>
      </Table>
    </div>
  )
