/**
 * Checks whether a Postgres function exists in the public schema.
 * Uses information_schema so no auth/role ambiguity — works with service_role.
 * Returns true if function exists; false otherwise.
 */
async function functionExists(
  db: ReturnType<typeof serviceClient>,
  fnName: string,
): Promise<boolean> {
  const { data, error } = await db
    .from('information_schema.routines' as never)
    .select('routine_name')
    .eq('routine_schema', 'public')
    .eq('routine_name', fnName)
    .limit(1)

  if (error) {
    // Fallback: try a raw query via rpc wrapper; if pg_proc is accessible use it
    // This handles Supabase setups that restrict information_schema reads
    const { data: procData, error: procError } = await db.rpc('pg_function_exists' as never, {
      fn_name: fnName,
    } as never)
    if (procError) {
      // Cannot determine — assume exists to avoid false skips
      return true
    }
    return Boolean(procData)
  }

  return Array.isArray(data) && data.length > 0
}

